import java.util.*;
import java.io.*;

public class Main {
    static final int N = 12;
    static final int INF = 1000000009;
    static final int[] move_x = {0, 1, 0, -1};
    static final int[] move_y = {1, 0, -1, 0};

    static class Coord {
        int r, c;
        Coord() {}
        Coord(int _r, int _c) {
            r = _r;
            c = _c;
        }
    }

    static int n, t;
    static char[][] mapA = new char[N][N];
    static char[][] mapB = new char[N][N];

    static int start_r, start_c;
    static int[][] dist = new int[N][N];

    static boolean[][][][] residuals = new boolean[N * 6][N][N][N][N];
    static boolean[][] reach = new boolean[N][N][N][N];

    static int[][] graph = new int[2 * N * N][2 * N * N];

    static int[] parent = new int[2 * N * N];
    static boolean[] visited_nodes = new boolean[2 * N * N];

    static boolean flow_search() {
        Arrays.fill(visited_nodes, false);
        Arrays.fill(parent, 0);
        Queue<Integer> q = new LinkedList<>();
        visited_nodes[0] = true;
        q.offer(0);
        while (!q.isEmpty()) {
            int node = q.poll();
            if (node == 2 * n * n + 1)
                return true;
            for (int h = 0; h <= 2 * n * n + 1; h++) {
                if (graph[node][h] != 0) {
                    if (!visited_nodes[h]) {
                        visited_nodes[h] = true;
                        parent[h] = node;
                        q.offer(h);
                    }
                }
            }
        }
        return false;
    }

    static void run_bfs(int[][] d, int sr, int sc) {
        boolean[][] visited = new boolean[n][n];
        for (int i = 0; i < n; ++i)
            Arrays.fill(d[i], INF);
        Queue<Coord> q = new LinkedList<>();
        visited[sr][sc] = true;
        d[sr][sc] = 0;
        q.offer(new Coord(sr, sc));
        while (!q.isEmpty()) {
            Coord cur = q.poll();
            for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
                int next_r = cur.r + move_x[dir_idx];
                int next_c = cur.c + move_y[dir_idx];
                if (next_r >= 0 && next_r < n && next_c >= 0 && next_c < n
                        && !visited[next_r][next_c]
                        && mapA[next_r][next_c] >= '0'
                        && mapA[next_r][next_c] <= '9') {
                    visited[next_r][next_c] = true;
                    d[next_r][next_c] = d[cur.r][cur.c] + 1;
                    q.offer(new Coord(next_r, next_c));
                }
            }
        }
    }

    static void process_input(Scanner sc) {
        n = sc.nextInt();
        t = sc.nextInt();
        for (int i = 0; i < n; ++i)
