                        if (!('0' <= mapA[x2][y2] && mapA[x2][y2] <= '9')) continue;
                        if (!reach[x1][y1][x2][y2]) continue;
                        graph[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                    }
                }
            }
        }

        while (flow_search()) {
            int min_flow = INF;
            for (int i = 2 * n * n + 1; i != 0; i = parent[i]) {
                min_flow = Math.min(min_flow, graph[parent[i]][i]);
            }
            for (int i = 2 * n * n + 1; i != 0; i = parent[i]) {
                graph[parent[i]][i] -= min_flow;
                graph[i][parent[i]] += min_flow;
            }
        }

        int total = 0;
        for (int i = 0; i <= 2 * n * n + 1; ++i)
            total += graph[i][0];

        System.out.println(total);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        process_input(sc);
        sc.close();
    }
